package com.huy.enterprise.shipment; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/shipments") @RequiredArgsConstructor public class ShipmentController {private final ShipmentService service;@GetMapping List<ShipmentResponse> all(){return service.all();}@GetMapping("/{id}") ShipmentResponse get(@PathVariable UUID id){return service.get(id);}@PostMapping @ResponseStatus(HttpStatus.CREATED) ShipmentResponse create(@Valid @RequestBody ShipmentRequest r){return service.save(null,r);}@PutMapping("/{id}") ShipmentResponse update(@PathVariable UUID id,@Valid @RequestBody ShipmentRequest r){return service.save(id,r);}@PatchMapping("/{id}/status") ShipmentResponse status(@PathVariable UUID id,@Valid @RequestBody ShipmentStatusRequest r){return service.status(id,r);}}
